  6	export interface RetryPolicy {
  7		readonly maxRetries: number;
  8		readonly baseDelayMs: number;
  9		readonly maxDelayMs: number;
 10	}
 11	
 12	export const DEFAULT_RETRY_POLICY: RetryPolicy = {
 13		maxRetries: 3,
 14		baseDelayMs: RETRY_BACKOFF_BASE_MS,
 15		maxDelayMs: RETRY_BACKOFF_MAX_MS,
 16	};
