 18	export function parseRetryAfterMs(
 19		value: string | null,
 20		now = Date.now(),
 21	): number | undefined {
 22		if (!value) return undefined;
 23		const seconds = Number(value);
 24		if (Number.isFinite(seconds) && seconds >= 0) {
 25			return Math.round(seconds * 1_000);
 26		}
 27		const dateMillis = Date.parse(value);
 28		return Number.isNaN(dateMillis) ? undefined : Math.max(0, dateMillis - now);
 29	}
