 31	/**
 32	 * Calculate the next retry delay without performing I/O.
 33	 *
 34	 * Keeping this policy pure makes it independently testable and provides the
 35	 * seam for replacing the imperative retry loop with an Effect Schedule.
 36	 */
 37	export function getRetryDelayMs(
 38		error: Pick<HevyHttpError, "status" | "headers">,
 39		retryAttempt: number,
 40		policy: RetryPolicy = DEFAULT_RETRY_POLICY,
 41		randomInt = (maxExclusive: number) =>
 42			Math.floor(Math.random() * maxExclusive),
 43	): number {
 44		const exponential = Math.min(
 45			policy.maxDelayMs,
 46			policy.baseDelayMs * 2 ** Math.max(0, retryAttempt - 1),
 47		);
 48		const retryAfter =
 49			error.status === 429
 50				? parseRetryAfterMs(error.headers?.get("retry-after") ?? null)
 51				: undefined;
 52		const lowerBound =
 53			retryAfter === undefined ? exponential : Math.max(exponential, retryAfter);
 54		const jitterLimit =
 55			retryAfter === undefined
 56				? 250
 57				: Math.min(250, Math.max(1, retryAfter * 0.1));
 58		const jitter = randomInt(Math.ceil(jitterLimit));
 59		return lowerBound + jitter;
 60	}
