 72	export interface RetryScheduleOptions<ScheduleError = never> {
 73		/**
 74		 * Decides whether the schedule may continue for the current failure.
 75		 * Effect 4 exposes this as `Schedule.while` over schedule metadata,
 76		 * including the input failure.
 77		 */
 78		readonly whileInput?: (
 79			input: RetryScheduleInput,
 80			attempt: number,
 81		) => boolean | Effect.Effect<boolean, never>;
 82		/**
 83		 * Optional adapter for callers that need to observe or bound a calculated
 84		 * delay. The returned duration is the wait that Schedule will own.
 85		 */
 86		readonly delay?: (
 87			input: RetryScheduleInput,
 88			attempt: number,
 89			delayMs: number,
 90		) => Effect.Effect<Duration.Input, ScheduleError>;
 91	}
