 93	/**
 94	 * Builds the Effect schedule used by retrying client programs.
 95	 *
 96	 * The schedule owns retry timing, recurrence, and the input predicate. The
 97	 * client supplies the safety predicate and optional delay adapter for
 98	 * observation or deadline bounding. Jitter stays behind the injectable
 99	 * `randomInt` seam (tests pass `() => 0`); it is deliberately sync so the
100	 * pure `getRetryDelayMs` policy needs no Effect context.
101	 */
102	export function createRetrySchedule<ScheduleError = never>(
103		maxRetries: number,
104		policy: RetryPolicy = DEFAULT_RETRY_POLICY,
105		randomInt = (maxExclusive: number) =>
106			Math.floor(Math.random() * maxExclusive),
107		options: RetryScheduleOptions<ScheduleError> = {},
108	): Schedule.Schedule<number, RetryScheduleInput, ScheduleError> {
109		return Schedule.recurs(Math.max(0, maxRetries)).pipe(
110			Schedule.while(
111				({ input, attempt }: Schedule.Metadata<number, RetryScheduleInput>) =>
112					options.whileInput?.(input, attempt) ?? true,
113			),
114			Schedule.addDelay(
115				({ input, attempt }: Schedule.Metadata<number, RetryScheduleInput>) => {
116					const delayMs = getRetryDelayMs(input, attempt, policy, randomInt);
117					return options.delay
118						? options.delay(input, attempt, delayMs)
119						: Effect.succeed(Duration.millis(delayMs));
120				},
121			),
122		);
123	}
