126	/**
127	 * Bridge an external AbortSignal into fiber interruption.
128	 *
129	 * The signal's reason is preserved by the caller that collapses the
130	 * interruption. This helper owns only the interruption and listener lifecycle
131	 * so adapters can share the same race and cleanup semantics.
132	 */
133	export function interruptOnAbortSignal(
134		signal: AbortSignal,
135	): Effect.Effect<never> {
136		return Effect.callback<never, never>((resume, interruptionSignal) => {
137			const cleanup = () => {
138				signal.removeEventListener("abort", onAbort);
139				interruptionSignal.removeEventListener("abort", cleanup);
140			};
141			const onAbort = () => resume(Effect.interrupt);
142			if (signal.aborted) onAbort();
143			else signal.addEventListener("abort", onAbort, { once: true });
144			interruptionSignal.addEventListener("abort", cleanup, { once: true });
145			return Effect.sync(cleanup);
146		}).pipe(Effect.interruptible);
147	}
