149	/**
150	 * Bridge an external AbortSignal into a typed failure carrying the abort
151	 * reason (falling back to an AbortError DOMException).
152	 *
153	 * This is the shared implementation behind retry-backoff waits and catalog
154	 * loads: both race their work against abortion and must surface the reason
155	 * in the failure channel rather than interrupting the fiber. Callers that
156	 * need interruption instead use `interruptOnAbortSignal`.
157	 *
158	 * The error type defaults to `unknown` because abort reasons are untrusted
159	 * caller input. Adapters that promise a narrower channel instantiate `E`
160	 * explicitly; the cast is sound because the failure always escapes through
161	 * the adapter's own Promise edge, never through the typed Effect channel.
162	 */
163	export function failOnAbortSignal<E = unknown>(
164		signal: AbortSignal,
165	): Effect.Effect<never, E> {
166		const bridge = Effect.callback<never, unknown>(
167			(resume, interruptionSignal) => {
168				const fail = () =>
169					resume(
170						Effect.fail(
171							signal.reason ??
172								new DOMException("Operation canceled", "AbortError"),
173						),
174					);
175				const cleanup = () => {
176					signal.removeEventListener("abort", fail);
177					interruptionSignal.removeEventListener("abort", cleanup);
178				};
179				if (signal.aborted) {
180					fail();
181					return;
182				}
183				signal.addEventListener("abort", fail, { once: true });
184				interruptionSignal.addEventListener("abort", cleanup, { once: true });
185				return Effect.sync(cleanup);
186			},
187		).pipe(Effect.interruptible);
188		return bridge as Effect.Effect<never, E>;
189	}
