210	/** Typed internal channel for a dispatch or response-consumption failure. */
211	export class AttemptFailure extends Data.TaggedError("AttemptFailure")<{
212		readonly cause: unknown;
213		readonly method: string;
214		readonly endpoint: string;
215		readonly phase: HevyRequestPhase;
216		readonly operationSafety: HevyOperationSafety;
217		readonly commitState: HevyCommitState;
218		readonly responseConfirmed: boolean;
219		readonly deadline?: number;
