223	/**
224	 * Adapt one asynchronous attempt to Effect while retaining the metadata
225	 * needed by the transition policy if the adapter itself throws.
226	 */
227	export function attemptEffect<A>(
228		options: AttemptFailureOptions & {
229			readonly run: (signal: AbortSignal) => Promise<A>;
230		},
231	): Effect.Effect<A, AttemptFailure> {
232		return Effect.tryPromise({
233			try: options.run,
234			catch: (cause) =>
235				new AttemptFailure({
236					cause,
237					method: options.method,
238					endpoint: options.endpoint,
239					phase: options.phase,
240					operationSafety: options.operationSafety,
241					commitState: options.commitState,
242					responseConfirmed: options.responseConfirmed,
243					deadline: options.deadline,
244					retryCount: options.retryCount,
245				}),
246		});
247	}
