249	/** Make observer and resource finalizers idempotent at their Effect seam. */
250	export function finalizeOnce(finalizer: () => void): () => void {
251		let finalized = false;
252		return () => {
253			if (finalized) return;
254			finalized = true;
255			try {
256				finalizer();
257			} catch {
258				// Resource finalization is best-effort and cannot replace settlement.
