267	export interface BackoffFailureOptions {
268		readonly cause: unknown;
269		readonly method: string;
270		readonly endpoint: string;
271		readonly phase: "backoff";
272		readonly operationSafety: HevyOperationSafety;
273		readonly deadline?: number;
274	}
