274	}
275	
276	/** Internal typed failure used while adapting a retry wait. */
277	export class BackoffFailure extends Data.TaggedError("BackoffFailure")<{
278		readonly cause: unknown;
279		readonly method: string;
280		readonly endpoint: string;
281		readonly phase: "backoff";
282		readonly operationSafety: HevyOperationSafety;
283		readonly deadline?: number;
284	}> {}
285	
286	/**
287	 * Wait using the Effect Clock while still observing the operation signal.
288	 * This is deliberately separate from the Promise adapter so TestClock can
289	 * control the actual production retry wait.
290	 */
291	export function effectClockSleep(
292		delayMs: number,
293		signal: AbortSignal,
294	): Effect.Effect<void, unknown> {
295		if (signal.aborted) {
296			return Effect.fail(
297				signal.reason ?? new DOMException("Operation canceled", "AbortError"),
298			);
299		}
300		const sleep = Effect.sleep(Duration.millis(Math.max(0, delayMs)));
301		return Effect.raceFirst(sleep, failOnAbortSignal(signal)).pipe(Effect.asVoid);
302	}
303	
304	/**
305	 * Adapt the established Promise sleep hook to an interruptible Effect.
306	 * Synchronous throws are captured by tryPromise just like rejections.
307	 */
308	export function customPromiseSleep(
309		delayMs: number,
310		signal: AbortSignal,
311		sleep: (milliseconds: number, signal?: AbortSignal) => Promise<void>,
312		deadline?: number,
313	): Effect.Effect<void, unknown> {
314		return Effect.tryPromise({
315			try: (interruptionSignal) => {
316				if (signal.aborted) {
317					return Promise.reject(
318						signal.reason ?? new DOMException("Operation canceled", "AbortError"),
319					);
320				}
321				return new Promise<void>((resolve, reject) => {
322					let settled = false;
323					const cleanup = () => {
324						signal.removeEventListener("abort", onOperationAbort);
325						interruptionSignal.removeEventListener("abort", onInterruptionAbort);
326					};
327					const settleReject = (cause: unknown) => {
328						if (settled) return;
329						settled = true;
330						cleanup();
331						reject(cause);
332					};
333					const onOperationAbort = () =>
334						settleReject(
335							signal.reason ??
336								new DOMException("Operation canceled", "AbortError"),
337						);
338					const onInterruptionAbort = () =>
339						settleReject(new DOMException("Effect interrupted", "AbortError"));
340					signal.addEventListener("abort", onOperationAbort, { once: true });
341					interruptionSignal.addEventListener("abort", onInterruptionAbort, {
342						once: true,
343					});
344					if (signal.aborted) {
345						onOperationAbort();
346						return;
347					}
348					try {
349						Promise.resolve(sleep(delayMs, signal)).then(() => {
350							if (settled) return;
351							settled = true;
352							cleanup();
353							resolve();
354						}, settleReject);
355					} catch (cause) {
356						settleReject(cause);
357					}
358				});
359			},
360			catch: (cause) => cause,
361		}).pipe(
362			Effect.flatMap(() =>
363				deadline === undefined
364					? Effect.void
365					: Effect.flatMap(Clock.currentTimeMillis, (now) =>
366							now >= deadline
367								? Effect.fail(
368										new Cause.TimeoutError("Retry backoff deadline exceeded"),
369									)
370								: Effect.void,
371						),
372			),
373		);
374	}
375	
376	export function retryBackoff(
377		options: BackoffFailureOptions & {
378			readonly delayMs: number;
379			readonly sleep?: (
380				milliseconds: number,
381				signal?: AbortSignal,
382			) => Promise<void>;
383			readonly signal: AbortSignal;
384		},
385	): Effect.Effect<void, BackoffFailure> {
386		const wait = options.sleep
387			? customPromiseSleep(
388					options.delayMs,
389					options.signal,
390					options.sleep,
391					options.deadline,
392				)
393			: effectClockSleep(options.delayMs, options.signal);
394		return wait.pipe(
395			Effect.mapError(
396				(cause) =>
397					new BackoffFailure({
398						cause,
399						method: options.method,
400						endpoint: options.endpoint,
401						phase: "backoff",
402						operationSafety: options.operationSafety,
403						deadline: options.deadline,
404					}),
405			),
406		);
407	}

