284	function boundedRandomInt(maxExclusive: number): number {
285		if (maxExclusive <= 1) return 0;
286		const random = new Uint32Array(1);
287		const cryptoApi = (
288			globalThis as typeof globalThis & {
289				crypto: { getRandomValues(values: Uint32Array): Uint32Array };
290			}
291		).crypto;
292		cryptoApi.getRandomValues(random);
293		return Math.floor((random[0] / 2 ** 32) * maxExclusive);
