296	function buildUrl(baseUrl: string, config: RequestConfig<unknown>): URL {
297		if (!config.url?.startsWith("/v1/")) {
298			throw new HevyHttpError("Invalid Hevy API endpoint", {
299				method: config.method ?? "GET",
300				endpoint: "unknown",
301				code: "HEVY_INVALID_ENDPOINT",
302			});
303		}
304		let resolvedUrl = config.url;
305		if (config.path && isObject(config.path)) {
306			for (const [key, value] of Object.entries(config.path)) {
307				if (value !== undefined) {
308					resolvedUrl = resolvedUrl.replaceAll(
309						`{${key}}`,
310						encodeURIComponent(value === null ? "null" : String(value)),
311					);
312				}
313			}
314		}
315		const url = new URL(resolvedUrl, baseUrl);
316		const query = config.query ?? config.params;
317		if (query && isObject(query)) {
318			for (const [key, value] of Object.entries(query)) {
319				if (value !== undefined) {
