 78	/** Resolve a raw request path or a canonical template without exposing IDs. */
 79	export function resolveHevyEndpoint(path: string): HevyEndpointResolution {
 80		const candidate = identityPath(path);
 81		let endpoint: HevyEndpointTemplate | undefined;
 82		if (STATIC_ENDPOINTS.has(candidate as HevyEndpointTemplate)) {
 83			endpoint = candidate as HevyEndpointTemplate;
 84		} else {
 85			for (const [prefix, template] of DYNAMIC_ENDPOINTS) {
 86				const id = candidate.slice(prefix.length);
 87				if (candidate.startsWith(prefix) && id.length > 0 && !id.includes("/")) {
 88					endpoint = template;
 89					break;
