363	function safeRetryHeaders(
364		headers: Headers | undefined,
365		secrets: readonly string[] | undefined,
366	): Headers | undefined {
367		if (!headers) return undefined;
368		try {
369			const retryAfter = headers.get("retry-after");
370			if (retryAfter === null || retryAfter.length > 128) return undefined;
371			if (
372				(secrets ?? []).some(
373					(secret) => secret.length > 0 && retryAfter.includes(secret),
374				)
375			) {
376				return undefined;
377			}
378			const numeric = Number(retryAfter);
379			if (
380				(Number.isFinite(numeric) && numeric >= 0) ||
381				!Number.isNaN(Date.parse(retryAfter))
382			) {
383				return new Headers({ "retry-after": retryAfter });
384			}
385		} catch {
386			// Untrusted header implementations must not affect error construction.
387		}
388		return undefined;
389	}
