437	function responseErrorText<T>(value: T): string | undefined {
438		if (!isResponseErrorBody(value)) return undefined;
439		for (const key of RESPONSE_ERROR_KEYS) {
440			const candidate = ownValue(value, key);
441			if (isString(candidate)) return candidate;
442			if (!isResponseErrorBody(candidate)) continue;
443			const nestedMessage = ownValue(candidate, "message");
444			if (isString(nestedMessage)) return nestedMessage;
445			const nestedDetail = ownValue(candidate, "detail");
446			if (isString(nestedDetail)) return nestedDetail;
447		}
448		return undefined;
