451	function removeControlCharacters(value: string): string {
452		let output = "";
453		for (const character of value) {
454			const codePoint = character.codePointAt(0) ?? 0;
455			if (codePoint <= 0x1f || codePoint === 0x7f) {
456				if (codePoint === 0x09 || codePoint === 0x0a || codePoint === 0x0d) {
457					output += " ";
458				}
459				continue;
460			}
461			output += character;
462		}
463		return output;
464	}
