472	export function sanitizeResponseErrorText(
473		value: string,
474		secrets: readonly string[] = [],
475	): string {
476		const bounded = removeControlCharacters(
477			value.slice(0, MAX_RESPONSE_ERROR_INPUT_LENGTH),
478		);
479		let sanitized = bounded
480			.replace(COOKIE_ASSIGNMENT, "$1[REDACTED]")
481			.replace(SECRET_ASSIGNMENT, "$1[REDACTED]")
482			.replace(BEARER_TOKEN, "Bearer [REDACTED]")
483			.replace(JSON_WEB_TOKEN, "[JWT_REDACTED]")
484			.replace(SECRET_QUERY_PARAMETER, "$1[REDACTED]")
485			.replace(HTTP_URL, "[URL_REDACTED]")
486			.replace(EMAIL, "[EMAIL_REDACTED]")
487			.replace(UUID, "[ID_REDACTED]")
488			.replace(/\s+/g, " ")
489			.trim();
490		for (const secret of secrets) {
491			if (secret.length > 0)
492				sanitized = sanitized.split(secret).join("[REDACTED]");
493		}
494		return truncate(sanitized);
495	}
