554	export const mergeConfig = <T extends RequestConfig>(
555		...configs: Array<Partial<T>>
556	): Partial<T> => {
557		return configs.reduce<Partial<T>>((merged, nextConfig) => {
558			return {
559				...merged,
560				...nextConfig,
561				headers: {
562					...normalizeHeaders(merged.headers),
563					...normalizeHeaders(nextConfig.headers),
564				},
565			};
566		}, {});
