571	export type Client = <TData, _TError = unknown, TVariables = unknown>(
572		requestConfig: RequestConfig<TVariables>,
573	) => Promise<ResponseConfig<TData>>;
574	
575	export const fetch = async <TData, _TError = unknown, TVariables = unknown>(
576		paramsConfig: RequestConfig<TVariables>,
577	): Promise<ResponseConfig<TData>> => {
578		const normalizedParams = new URLSearchParams();
579		const requestConfig = mergeConfig(getConfig(), paramsConfig);
580		const query = requestConfig.query ?? requestConfig.params;
581		const bodyPayload = requestConfig.body ?? requestConfig.data;
582		const pathParams = requestConfig.path;
583	
584		Object.entries(query || {}).forEach(([key, value]) => {
585			if (value !== undefined) {
586				normalizedParams.append(key, value === null ? "null" : value.toString());
587			}
588		});
589	
590		let resolvedPath = requestConfig.url ?? "";
591		Object.entries(pathParams || {}).forEach(([key, value]) => {
592			if (value !== undefined) {
593				resolvedPath = resolvedPath.replaceAll(
594					`{${key}}`,
595					encodeURIComponent(value === null ? "null" : value.toString()),
596				);
597			}
598		});
599	
600		let targetUrl = [requestConfig.baseURL, resolvedPath]
601			.filter(Boolean)
602			.join("");
603		if (query) targetUrl += `?${normalizedParams}`;
604	
605		const response = await globalThis.fetch(targetUrl, {
606			method: requestConfig.method?.toUpperCase(),
607			body:
608				bodyPayload instanceof FormData
609					? bodyPayload
610					: JSON.stringify(bodyPayload),
611			signal: requestConfig.signal,
612			headers: requestConfig.headers,
613		});
614	
615		const data =
616			[204, 205, 304].includes(response.status) || !response.body
617				? {}
618				: await response.json();
619	
620		return {
621			data: data as TData,
622			status: response.status,
623			statusText: response.statusText,
624			headers: response.headers,
625		};
626	};
