 543	/** Execute one dispatch/response attempt and retain its safe phase state. */
 544	async function executeRequestAttempt<TData>(
 545		options: RequestAttemptExecutionOptions,
 546	): Promise<RequestAttemptOutcome<TData>> {
 547		let phase: HevyRequestPhase = "before-dispatch";
 548		let responseConfirmed = false;
 549		const setPhase = (nextPhase: HevyRequestPhase) => {
 550			phase = nextPhase;
 551			options.onPhaseChange?.(nextPhase);
 552		};
 553		try {
 554			const result = await runRequestObservation(
 555				options.observationScope,
 556				async () => {
 557					const payload = options.normalized.body ?? options.normalized.data;
 558					const headers = new Headers({ "api-key": options.apiKey });
 559					if (payload !== undefined && !(payload instanceof FormData)) {
 560						headers.set("content-type", "application/json");
 561					}
 562					const requestInit: RequestInit = {
 563						method: options.method,
 564						headers,
 565						redirect: "manual",
 566						body:
 567							payload instanceof FormData
 568								? payload
 569								: payload === undefined
 570									? undefined
 571									: JSON.stringify(payload),
 572						signal: options.callerSignal
 573							? AbortSignal.any([
 574									options.interruptionSignal,
 575									options.callerSignal,
 576								])
 577							: options.interruptionSignal,
 578					};
 579					let fetchPromise: Promise<Response>;
 580					try {
 581						const fetchImplementation = options.fetchImplementation;
 582						fetchPromise = Promise.resolve(
 583							fetchImplementation(options.url, requestInit),
 584						);
 585					} catch (error) {
 586						setPhase("before-dispatch");
 587						throw error;
 588					}
 589					setPhase("dispatch");
 590					const response = await fetchPromise;
 591					setPhase("response-headers");
 592					setPhase("response-content");
 593					const cancelBody = finalizeOnce(() => {
 594						const body = response.body;
 595						if (!body || body.locked) return;
 596						void body.cancel().catch(() => {});
 597					});
 598					options.onBodyFailure?.(cancelBody);
 599					const data = await parseResponseData(response, cancelBody);
 600					if (!response.ok) {
 601						throw new HevyHttpError(
 602							`Hevy API request failed (HTTP ${response.status})`,
 603							{
 604								status: response.status,
 605								statusText: response.statusText,
 606								data,
 607								headers: response.headers,
 608								method: options.method,
 609								endpoint: options.endpoint,
 610								redact: [options.apiKey],
 611								phase,
 612								operationSafety: options.safety,
 613								commitState: commitStateFor(options.safety, phase, false),
 614								safeToRetry: false,
 615							},
 616						);
 617					}
 618					responseConfirmed = true;
 619					const observation: HevyRequestObservation = {
 620						method: options.method,
 621						endpoint: options.endpoint,
 622						status: response.status,
 623						durationMs: Date.now() - options.startedAt,
 624						retryCount: options.retryCount,
 625						outcome: "success",
 626						phase: "completed",
 627						operationSafety: options.safety,
 628						commitState: "confirmed",
 629						safeToRetry: false,
 630					};
 631					if (options.onAttemptComplete) {
 632						options.onAttemptComplete(observation);
 633					} else {
 634						finishRequestObservation(options.observationScope, observation);
 635						emitRequestObservation(options.onRequestComplete, observation);
 636					}
 637					return {
 638						data: data as TData,
 639						status: response.status,
 640						statusText: response.statusText,
 641						headers: response.headers,
 642					};
 643				},
 644			);
 645			return { ok: true, result };
 646		} catch (cause) {
 647			return { ok: false, cause, phase, responseConfirmed };
 648		}
 649	}
