 866		const createRequestEffect = <TData, TVariables = unknown>(
 867			config: RequestConfig<TVariables> & InternalRequestControl,
 868		): Effect.Effect<ResponseConfig<TData>, unknown> => {
 869			const normalized = {
 870				...clientConfig,
 871				...config,
 872			} as RequestConfig<unknown> & InternalRequestControl;
 873			const { method, endpoint, page } = getRequestContext(normalized);
 874			const urlResult = buildUrlResult(baseUrl, normalized);
 875			if (isHevyHttpError(urlResult)) return Effect.fail(urlResult);
 876			const url = urlResult;
 877			// Composed operations may provide their descriptor safety. Raw generated
 878			// calls intentionally fall back to the HTTP method mapping.
 879			const safety = normalized.hevySafety ?? operationSafetyForMethod(method);
