 884			// beyond it, so the deadline retry is disabled in that case.
 885			const operationTimeoutMs = normalizePositiveInteger(
 886				normalized.hevyTimeoutMs,
 887				timeoutMs,
 888			);
 889			let currentPhase: HevyRequestPhase = "before-dispatch";
 890			const requestEffect = Effect.suspend(() => {
 891				const operationStartedAt = Date.now();
 892				let deadline =
 893					normalized.hevyDeadline ??
 894					operationStartedAt + operationTimeoutMs * (maxGetRetries + 1);
 895				// A timed-out read gets one fresh attempt budget on retry, bounded
 896				// by the extended operation deadline. An explicit caller deadline
 897				// stays authoritative and is never extended.
 898				const operationDeadline =
 899					normalized.hevyDeadline ?? deadline + operationTimeoutMs;
 900				let retryCount = 0;
 901				let freeDeadlineRetryUsed = false;
 902				let activeRetryWaitScope: HevyRetryWaitScope | undefined;
 903				const finishActiveRetryWait = () => {
 904					const scope = activeRetryWaitScope;
 905					activeRetryWaitScope = undefined;
 906					finishRetryWait(scope);
 907				};
 908	
 909				const requestAttempt = Effect.suspend(() => {
 910					finishActiveRetryWait();
 911					currentPhase = "before-dispatch";
 912					const attemptDeadline = Math.min(
 913						deadline,
 914						Date.now() + operationTimeoutMs,
 915					);
 916					const remaining = remainingDeadlineMs(attemptDeadline);
 917					if (normalized.signal?.aborted || remaining <= 0) {
 918						const deadlineExceeded = remaining <= 0;
 919						const phase =
 920							retryCount > 0 && deadlineExceeded
 921								? ("backoff" as const)
 922								: ("before-dispatch" as const);
 923						currentPhase = phase;
 924						const error = createExecutionError({
 925							method,
 926							endpoint,
 927							safety,
 928							phase,
 929							deadlineExceeded,
 930							canceled: !deadlineExceeded,
 931							callerCanceled: !deadlineExceeded && normalized.signal?.aborted,
 932						});
 933						emitRequestObservation(options.onRequestComplete, {
 934							method,
 935							endpoint,
 936							status: 0,
 937							durationMs: 0,
 938							retryCount,
 939							outcome: error.outcome ?? "cancelled",
 940							phase: error.phase,
 941							operationSafety: safety,
 942							commitState: error.commitState,
 943							safeToRetry: false,
 944							error: {
 945								code: error.code,
 946								category: "NetworkError",
 947							},
