  2	 * Runtime-neutral execution control shared by every Hevy adapter.
  3	 *
  4	 * The client owns this vocabulary so adapters can only present the same
  5	 * outcome; they cannot accidentally grow incompatible retry/error taxonomies.
  6	 */
  7	export type HevyOperationSafety =
  8		| "read"
  9		| "idempotent-write"
 10		| "non-idempotent-write";
 11	
 12	export type HevyRequestPhase =
 13		| "before-dispatch"
 14		| "dispatch"
 15		| "response-headers"
 16		| "response-content"
 17		| "backoff"
 18		| "completed";
 19	
 20	export type HevyCommitState = "not_sent" | "confirmed" | "unknown";
 21	
 22	export type HevyExecutionOutcome =
 23		| "success"
 24		| "expected"
 25		| "retryable_failure"
 26		| "terminal_failure"
 27		| "cancelled"
 28		| "deadline_exceeded";
 29	
 30	export interface HevyExecutionOutcomeDetails {
 31		readonly outcome: HevyExecutionOutcome;
 32		readonly phase: HevyRequestPhase;
 33		readonly operation_safety: HevyOperationSafety;
 34		readonly commit_state: HevyCommitState;
 35		readonly safe_to_retry: boolean;
 36		readonly status?: number;
 37		readonly code?: string;
 38	}
 39	
 40	/** Caller-owned control for one logical operation (not one retry attempt). */
 41	export interface HevyExecutionControl {
 42		readonly signal?: AbortSignal;
 43		/** Absolute epoch milliseconds supplied by the caller; never reset. */
 44		readonly deadline?: number;
 45	}
 46	
 47	export interface HevyExecutionOptions extends HevyExecutionControl {
 48		/** Per-operation timeout in milliseconds; overrides the client default. */
 49		readonly timeoutMs?: number;
 50	}
 51	
 52	/** Request options shared by the curated client and generated adapters. */
 53	export interface HevyRequestOptions extends HevyExecutionOptions {}
 54	
 55	export function isDeadlineExceeded(deadline: number | undefined): boolean {
 56		return deadline !== undefined && Date.now() >= deadline;
 57	}
 58	
 59	export function remainingDeadlineMs(deadline: number | undefined): number {
 60		return deadline === undefined
 61			? Number.POSITIVE_INFINITY
 62			: deadline - Date.now();
 63	}
 64	
 65	export function operationSafetyForMethod(method: string): HevyOperationSafety {
 66		const normalizedMethod = method.toUpperCase();
 67		if (["GET", "HEAD", "OPTIONS"].includes(normalizedMethod)) {
 68			return "read";
 69		}
 70		if (["PUT", "DELETE"].includes(normalizedMethod)) {
 71			return "idempotent-write";
 72		}
 73		return "non-idempotent-write";
 74	}
 75	
 76	export function canRetryOperation(
 77		safety: HevyOperationSafety,
 78		phase: HevyRequestPhase,
 79	): boolean {
 80		if (safety === "non-idempotent-write") return false;
 81		return (
 82			phase === "before-dispatch" ||
 83			phase === "dispatch" ||
 84			phase === "response-headers" ||
 85			phase === "response-content" ||
 86			phase === "backoff"
 87		);
 88	}
 89	
 90	export function commitStateFor(
 91		safety: HevyOperationSafety,
 92		phase: HevyRequestPhase,
 93		confirmed: boolean,
 94	): HevyCommitState {
 95		if (safety === "read") return confirmed ? "confirmed" : "not_sent";
 96		if (confirmed) return "confirmed";
 97		return phase === "before-dispatch" ? "not_sent" : "unknown";
 98	}
 99	
100	export function isAbortLike<T>(error: T): boolean {
101		if (!(error instanceof Error)) return false;
102		return error.name === "AbortError" || error.name === "TimeoutError";
103	}
