    12	function requestUrl(input: RequestInfo | URL): string {
    13		if (input instanceof URL) return input.href;
    14		if (input instanceof Request) return input.url;
    15		return input;
    16	}
    17	
    18	function response(data: JsonObject, status = 200): Response {
    19		return new Response(JSON.stringify(data), {
    20			status,
    21			headers: { "content-type": "application/json" },
    22		});
    23	}
    24	
    25	describe("request-local retry state", () => {
    26		it("resets retry indexes for sequential logical requests", async () => {
    27			vi.useFakeTimers();
    28			try {
    29				const starts: number[] = [];
    30				const fetchMock = vi
    31					.fn()
    32					.mockResolvedValueOnce(response({}, 503))
    33					.mockResolvedValueOnce(response({ request: 1 }))
    34					.mockResolvedValueOnce(response({}, 503))
    35					.mockResolvedValueOnce(response({ request: 2 }));
    36				const client = createHevyClient({
    37					apiKey: "test-key",
    38					fetch: fetchMock,
    39					maxGetRetries: 1,
    40					sleep: async () => {},
    41					onRequestStart: ({ retryCount }) => {
    42						starts.push(retryCount);
    43					},
    44				});
    45	
    46				const p1 = client.getUserInfo();
    47				await vi.runAllTimersAsync();
    48				await expect(p1).resolves.toEqual({ request: 1 });
    49	
    50				const p2 = client.getUserInfo();
    51				await vi.runAllTimersAsync();
    52				await expect(p2).resolves.toEqual({ request: 2 });
    53	
    54				expect(fetchMock).toHaveBeenCalledTimes(4);
    55				expect(starts).toEqual([0, 1, 0, 1]);
    56			} finally {
    57				vi.useRealTimers();
    58			}
    59		});
    60	
    61		it("keeps retry indexes and budgets isolated for concurrent requests", async () => {
    62			vi.useFakeTimers();
    63			try {
    64				const starts: Array<{ endpoint: string; retryCount: number }> = [];
    65				const attemptsByEndpoint = new Map<string, number>();
    66				const fetchMock = vi.fn((input: RequestInfo | URL) => {
    67					const endpoint = new URL(requestUrl(input)).pathname;
    68					const attempt = (attemptsByEndpoint.get(endpoint) ?? 0) + 1;
    69					attemptsByEndpoint.set(endpoint, attempt);
    70					return Promise.resolve(
    71						attempt === 1 ? response({}, 503) : response({ endpoint }),
    72					);
    73				});
    74				const client = createHevyClient({
    75					apiKey: "test-key",
    76					fetch: fetchMock,
    77					maxGetRetries: 1,
    78					sleep: async () => {},
    79					onRequestStart: ({ endpoint, retryCount }) => {
    80						starts.push({ endpoint, retryCount });
    81					},
    82				});
    83	
    84				const promise = Promise.all([client.getWorkouts(), client.getRoutines()]);
    85				await vi.runAllTimersAsync();
    86				const [workouts, routines] = await promise;
    87	
    88				expect(workouts).toEqual({ endpoint: "/v1/workouts" });
    89				expect(routines).toEqual({ endpoint: "/v1/routines" });
    90				expect(fetchMock).toHaveBeenCalledTimes(4);
    91				expect(
    92					starts.map(({ retryCount }) => retryCount).sort((a, b) => a - b),
    93				).toEqual([0, 0, 1, 1]);
    94			} finally {
    95				vi.useRealTimers();
    96			}
    97		});
    98	
    99		it.each([
   100			["fractional values floor to zero", 0.9, 1],
   101			["negative values use the default", -1, 4],
   102		])("normalizes retry option: %s", async (_label, maxGetRetries, calls) => {
   103			vi.useFakeTimers();
   104			try {
   105				const fetchMock = vi.fn().mockResolvedValue(response({}, 503));
   106				const client = createHevyClient({
   107					apiKey: "test-key",
   108					fetch: fetchMock,
   109					maxGetRetries,
   110					sleep: async () => {},
   111				});
   112	
   113				const promise = client.getUserInfo();
   114				const result = expect(promise).rejects.toMatchObject({
   115					code: HEVY_RETRY_EXHAUSTED_ERROR_CODE,
   116				});
   117				await vi.runAllTimersAsync();
   118				await result;
   119				expect(fetchMock).toHaveBeenCalledTimes(calls);
   120			} finally {
   121				vi.useRealTimers();
   122			}
   123		});
   124	
   125		it("does not let cancellation of one request cancel a concurrent request", async () => {
   126			const controller = new AbortController();
   127			let cancelledStarted!: () => void;
   128			const cancelledRequestStarted = new Promise<void>((resolve) => {
   129				cancelledStarted = resolve;
   130			});
   131			const fetchMock = vi.fn(
   132				(input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
   133					const endpoint = new URL(requestUrl(input)).pathname;
   134					if (endpoint === "/v1/workouts/cancelled-id") {
   135						cancelledStarted();
   136						return new Promise<Response>((_resolve, reject) => {
   137							init?.signal?.addEventListener(
   138								"abort",
   139								() => reject(init.signal?.reason),
   140								{ once: true },
   141							);
   142						});
   143					}
   144					return Promise.resolve(response({ recovered: true }));
   145				},
   146			);
   147			const client = createHevyClient({
   148				apiKey: "test-key",
   149				fetch: fetchMock,
   150				maxGetRetries: 1,
   151				onRequestStart: () => ({ finish: vi.fn() }),
   152			});
   153	
   154			const cancelled = client.getWorkout("cancelled-id", {
   155				signal: controller.signal,
   156			});
   157			await cancelledRequestStarted;
   158			const successful = client.getUserInfo();
   159			controller.abort(new DOMException("cancelled", "AbortError"));
   160	
   161			await expect(cancelled).rejects.toMatchObject({
   162				code: HEVY_REQUEST_ABORTED_ERROR_CODE,
   163			});
   164			await expect(successful).resolves.toEqual({ recovered: true });
   165			expect(fetchMock).toHaveBeenCalledTimes(2);
   166		});
   167	});
