		const hung = new Promise((resolve) => setTimeout(() => resolve("hung"), 500));
		expect(await Promise.race([settled, hung])).toBe(
			HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
		);
	});

	it("probe: no abort listeners accumulate on a long-lived caller signal", async () => {
		const controller = new AbortController();
		const fetchMock = vi.fn(async () => json({ ok: true }));
		const client = createHevyClient({ apiKey: "fake-key", fetch: fetchMock });
		for (let index = 0; index < 50; index += 1) {
			await client.getUserInfo({ signal: controller.signal });
		}
		expect(getEventListeners(controller.signal, "abort").length).toBe(0);
	});

	it("probe: a 200 non-JSON body is not reported as success data", async () => {
		const fetchMock = vi.fn().mockResolvedValue(
			new Response("<html>captive portal</html>", {
				status: 200,
				headers: { "content-type": "text/html" },
			}),
		);
		const client = createHevyClient({ apiKey: "fake-key", fetch: fetchMock });
		const outcome = await client.getUserInfo().then(
			(value) => typeof value,
			() => "rejected",
		);
		expect(outcome).toBe("rejected");
	});
});

